#!/usr/bin/env bash
# Validate ONE commit message against Conventional Commits.
# Used by the commit-msg hook (arg = path of the message file) and by check-commit-range.sh.
# Usage: check-commit-message.sh <message-file>
set -euo pipefail

subject=$(head -n 1 "${1:?usage: $0 <message-file>}")

# Merge and revert commits generated by git are allowed as they are.
if [[ "$subject" =~ ^(Merge|Revert)\  ]]; then
  exit 0
fi

pattern='^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(\([a-zA-Z0-9_.-]+\))?!?: .+$'
if ! [[ "$subject" =~ $pattern ]]; then
  {
    echo "error: not a Conventional Commit: \"$subject\""
    echo "  expected: <type>(<scope>)?: <description>"
    echo "  types: feat fix docs style refactor perf test build ci chore revert"
  } >&2
  exit 1
fi
